# SPDX-License-Identifier: MIT
"""vendored-core-drift (HARD): a vendored `_core/` copy, or any file stamped GENERATED by
tools/sync_core.py, must match what was generated — checked from the file alone (content
hash in the stamp), and against shared/sopcore/ when the plugin sits in a repo that has it."""
import os, shutil, sys, tempfile, unittest
PLUGIN = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
sys.path.insert(0, PLUGIN)
from pluginforge.rules import vendored
from pluginforge._core import vendor

OWN_CORE = os.path.join(PLUGIN, "pluginforge", "_core")


def _plugin(root, pkg="demo"):
    pd = os.path.join(root, "plugins", "p")
    shutil.copytree(OWN_CORE, os.path.join(pd, pkg, "_core"),
                    ignore=shutil.ignore_patterns("__pycache__"))
    return pd


def _append(path, text):
    with open(path, "a", encoding="utf-8") as f:
        f.write(text)


class TestVendoredCoreDrift(unittest.TestCase):
    def test_intact_copy_is_clean(self):
        with tempfile.TemporaryDirectory() as d:
            self.assertEqual(vendored.check(_plugin(d), strict=True), [])

    def test_no_core_is_clean(self):
        with tempfile.TemporaryDirectory() as d:
            self.assertEqual(vendored.check(d, strict=True), [])

    def test_hand_edited_copy_is_hard(self):
        with tempfile.TemporaryDirectory() as d:
            pd = _plugin(d)
            _append(os.path.join(pd, "demo", "_core", "markers.py"), "TBD = 'x'\n")
            out = vendored.check(pd, strict=False)   # not strict-only: drift is a correctness bug
            self.assertEqual([(f.rule, f.severity) for f in out], [("vendored-core-drift", "HARD")])
            self.assertIn("markers.py", out[0].location)

    def test_edited_generated_harness_is_hard(self):
        with tempfile.TemporaryDirectory() as d:
            os.makedirs(os.path.join(d, "tests"))
            p = os.path.join(d, "tests", "verify.py")
            with open(p, "w", encoding="utf-8") as f:
                f.write(vendor.stamp("print(1)\n", "shared/sopcore/harness.py") + "print(2)\n")
            self.assertEqual(len(vendored.check(d, strict=True)), 1)

    def test_stale_against_shared_source_is_hard(self):
        with tempfile.TemporaryDirectory() as d:
            pd = _plugin(d)
            shared = os.path.join(d, "shared", "sopcore")
            shutil.copytree(OWN_CORE, shared, ignore=shutil.ignore_patterns("__pycache__"))
            for fn in os.listdir(shared):      # turn the copies back into sources
                p = os.path.join(shared, fn)
                if fn.endswith(".py"):
                    with open(p, encoding="utf-8") as f:
                        body = vendor.unstamp(f.read())[0]
                    with open(p, "w", encoding="utf-8") as f:
                        f.write(body)
            self.assertEqual(vendored.check(pd, strict=True), [])
            _append(os.path.join(shared, "markers.py"), "# source moved on\n")
            with open(os.path.join(shared, "newmod.py"), "w", encoding="utf-8") as f:
                f.write("# new\n")
            details = sorted(f.detail for f in vendored.check(pd, strict=True))
            self.assertEqual(len(details), 2)
            self.assertTrue(any("newmod.py" in x for x in details))
            self.assertTrue(any("markers.py" in x for x in details))


if __name__ == "__main__":
    unittest.main()
